#!/usr/bin/env bash
# SPDX-License-Identifier: GPL-3.0-only
# Assembles src/a2mask.S (the mask patch of a2start.exe) into src/a2mask.h, the byte array that
# src/a2start.c copies into the game. Run it after every change of src/a2mask.S; the tox env "build"
# checks that src/a2mask.h is up to date. Needs GNU as and objcopy.
#
#   .github/build-mask.sh [output]    (default: src/a2mask.h)
set -euo pipefail
cd "$(dirname "$0")/.."
out="${1:-src/a2mask.h}"
tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT
as --32 -o "$tmp/a.o" src/a2mask.S
objcopy -O binary -j .text "$tmp/a.o" "$tmp/a.bin"
{
  echo "/* SPDX-License-Identifier: GPL-3.0-only */"
  echo "/* Generated by .github/build-mask.sh from src/a2mask.S, do not edit. */"
  echo "static const unsigned char mask_code[] = {"
  od -An -v -tx1 "$tmp/a.bin" | sed -E 's/ ([0-9a-f]{2})/0x\1, /g; s/^/   /; s/, $/,/'
  echo "};"
} > "$out"
echo "$out written ($(stat -c %s "$tmp/a.bin") bytes)"
